use graph::prelude::DeploymentHash;
use graph::schema::InputSchema;

fn main() {
    // 1. skipDuplicates without immutable must fail validation
    let bad = r#"type Foo @entity(skipDuplicates: true) { id: ID! }"#;
    let errs = InputSchema::validate(
        graph::data::subgraph::LATEST_VERSION,
        bad,
        DeploymentHash::new("bad").unwrap(),
    );
    assert!(!errs.is_empty(), "skipDuplicates without immutable should fail");
    println!("bad schema errors: {:?}", errs);

    // 2. immutable + skipDuplicates is valid
    let gql = r#"
        type Dup @entity(immutable: true, skipDuplicates: true) { id: ID!, n: Int! }
        type Imm @entity(immutable: true) { id: ID!, n: Int! }
    "#;
    let schema = InputSchema::parse_latest(gql, DeploymentHash::new("ok").unwrap()).unwrap();

    let dup = schema.entity_type("Dup").unwrap();
    let imm = schema.entity_type("Imm").unwrap();
    assert!(dup.skip_duplicates(), "Dup must skip duplicates");
    assert!(!imm.skip_duplicates(), "Imm must not skip duplicates");
    assert!(dup.is_immutable() && imm.is_immutable());

    let mk = |et: &graph::schema::EntityType, block| {
        let data = schema.make_entity(vec![("id".into(), "a".into()), ("n".into(), 1.into())]).unwrap();
        EntityModification::insert(et.parse_key("a").unwrap(), data, block)
    };

    // Cross-block duplicate on skip type -> discarded, count stays 1
    let mut g = RowGroup::new(dup.clone());
    g.push(mk(&dup, 1), 1).unwrap();
    g.push(mk(&dup, 2), 2).expect("cross-block dup should be Ok");
    // Overwrite / Remove tolerated
    g.append_row(EntityModification::overwrite(dup.parse_key("a").unwrap(),
        schema.make_entity(vec![("id".into(), "a".into()), ("n".into(), 2.into())]).unwrap(), 3)).expect("overwrite ok");
    g.append_row(EntityModification::remove(dup.parse_key("a").unwrap(), 4)).expect("remove ok");
    println!("skip type OK");

    // Cross-block duplicate on plain immutable -> error
    let mut g2 = RowGroup::new(imm.clone());
    g2.push(mk(&imm, 1), 1).unwrap();
    assert!(g2.push(mk(&imm, 2), 2).is_err(), "plain immutable cross-block dup must error");
    println!("immutable type OK");
    println!("ALL CHECKS PASSED");
}
